 "definition": "شروط الوجوب هي ما تجب الصلاة بتوفره على المكلف: الإسلام والعقل والبلوغ. وشروط الصحة هي ما تصح به الصلاة: الطهارة من النجاسة، والطهارة من الحدث، وستر العورة، واستقبال القبلة، والعلم بدخول الوقت.",
 "hukm": "الحنفية والمالكية والشافعية يقسمون شروط الصلاة إلى شروط وجوب وشروط صحة، ويزيد المالكية قسماً ثالثاً هو شروط وجوب وصحة معاً. وفي الجدول اختلافهم فيمن زال عقله أو نام أو ارتد، وفي سن أمر الصبي بالصلاة.",
