 "n": 1,
 "name": "النية",
 "action": "نية الصلاة المعينة (ظهر أو عصر مثلاً) قبل التكبير.\nحكمها:: ركن عند الجمهور (المالكية والشافعية والحنابلة)، وشرط عند الحنفية.\nمعناها:: العزم على فعل العبادة تقرباً إلى الله تعالى، فلا تصح الصلاة بدونها عند الجمهور، ولا بد فيها عندهم من تعيين الفرضية ونوع الصلاة، هل هي ظهر أم عصر.\nالدليل:: قوله تعالى ﴿وما أمروا إلا ليعبدوا الله مخلصين له الدين﴾، وقوله ﷺ «إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى» (البخاري من حديث عمر، كما في تخريج الموسوعة وغير مدروس هنا). ونقلت الموسوعة الإجماع على اعتبار النية في الصلاة.",
 "dhikr": "النية عمل القلب، ولا يُذكر هنا لفظ مخصوص لها.",
