 "hanbali": "إن أدرك مع الإمام أي ركن قبل السجود وجبت متابعته. وإن اقتدى بعد السجدة الأولى قضاها بعد سلام الإمام ثم قضى ما فاته (نصاً). وفي رواية عن أحمد: كالمالكية في أنه إن لم يدرك ركعة فلا سجود عليه."
