 "definition": "هذا الدرس في سنن ما بعد تكبيرة الإحرام: دعاء الاستفتاح، والتعوذ، وقراءة شيء من القرآن بعد الفاتحة، والتأمين، وتكبيرات الانتقال. والبسملة ذكرت الموسوعة فيها خلافاً وأحالت تفصيله إلى مدخل آخر، فهي خارج هذا الدرس.",
 "hukm": "الاستفتاح سنة عند الحنفية والشافعية والحنابلة ومكروه عند المالكية. والتعوذ سنة عند الثلاثة ومكروه في الفرض عند المالكية دون النفل. والتأمين سنة باتفاق الفقهاء. والقراءة بعد الفاتحة سنة عند المالكية والشافعية والحنابلة، وواجبة عند الحنفية (درس الواجبات).",
 "pt": 1,
 "hukmKh": ["v7"],
 "hukmRef": "الموسوعة (مدخل صلاة). بداية النطاق ونهايته: https://muslim-library.com/keoj/volume/27/17861/ و https://muslim-library.com/keoj/volume/27/17869/",
 "labels": {
 "c": "التعريف",
 "p": "الاستفتاح والتعوذ",
 "o": "القراءة والتأمين",
 "s": "ملاحظات",
 "n": "ما لا يشمله الدرس"
 },
