 "pillars": [
 {
 "id": "p1",
 "ev": ["e1"],
 "kh": ["v1"],
 "t": "دعاء الاستفتاح",
 "d": "عند الجمهور (الحنفية والشافعية والحنابلة) سنة بعد تكبيرة الإحرام. وتذكر الموسوعة صيغتين: سبحانك اللهم وبحمدك، وصيغة وجهت وجهي، وتقول إن في السنة الصحيحة صيغاً كثيرة غيرهما. والمالكية يكرهونه.",
 "ref": "الموسوعة (مدخل صلاة): https://muslim-library.com/keoj/volume/27/17861/ و https://muslim-library.com/keoj/volume/27/17862/"
 },
 {
 "id": "p2",
 "kh": ["v2"],
 "t": "التعوذ",
 "d": "سنة بعد الاستفتاح وقبل القراءة عند الحنفية والشافعية والحنابلة، لقوله تعالى: فإذا قرأت القرآن فاستعذ بالله من الشيطان الرجيم. والمالكية يكرهونه في الفرض دون النفل.",
 "ref": "الموسوعة (مدخل صلاة): https://muslim-library.com/keoj/volume/27/17863/"
 }
 ],
 "obligations": [
 {
 "id": "o1",
 "kh": ["v3", "v4", "v5"],
 "t": "القراءة بعد الفاتحة",
 "d": "يسن عند الجمهور (المالكية والشافعية والحنابلة) أن يقرأ المصلي شيئاً من القرآن بعد الفاتحة. وتجوز السورة الكاملة وهي أفضل بلا خلاف بين الشافعية. ولا تجزئ السورة إن قرأها قبل الفاتحة.",
 "ref": "الموسوعة (مدخل صلاة): https://muslim-library.com/keoj/volume/27/17863/ و https://muslim-library.com/keoj/volume/27/17864/"
 },
 {
 "id": "o2",
 "ev": ["e2"],
 "kh": ["v6"],
 "t": "التأمين",
 "d": "اتفق الفقهاء على أن التأمين بعد الفاتحة سنة، لحديث أبي هريرة. ولا يفوت إلا بالشروع في غيره عند الشافعية والحنابلة، وعند الشافعية قول بفواته بالركوع.",
 "ref": "الموسوعة (مدخل صلاة): https://muslim-library.com/keoj/volume/27/17867/ و https://muslim-library.com/keoj/volume/27/17868/"
 }
 ],
 "sunan": [
 {
 "id": "s1",
 "t": "ملاحظة",
 "d": "الاستدلال المذكور لكل مذهب في الموسوعة ينسب لأصحابه. الدليل المنقول نصه بالحرف من صحيح البخاري فقط، وهو في صيغة من صيغ الاستفتاح وفي التأمين.",
 "ref": "الموسوعة (مدخل صلاة): https://muslim-library.com/keoj/volume/27/17861/ إلى https://muslim-library.com/keoj/volume/27/17868/"
 }
 ],
