 "d": "قال تعالى: حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين. قال السعدي: المحافظة عليها أداؤها بوقتها وشروطها وأركانها وخشوعها وجميع ما لها من واجب ومستحب. فيدخل في كلامه الواجب والمستحب معاً، وأحكام كل سنة وخلاف المذاهب فيها في تبويب الخلاف.",
