 "evidence": [
 {
 "id": "e1",
 "type": "hadith",
 "text": "اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَاىَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْ خَطَايَاىَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ",
 "ref": "صحيح البخاري 744 (من حديث أبي هريرة). دعاء في السكتة بين التكبير والقراءة. وهو صيغة من صيغ الاستفتاح.",
 "exact": true
 },
 {
 "id": "e2",
 "type": "hadith",
 "text": "إِذَا قَالَ الإِمَامُ {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلاَ الضَّالِّينَ} فَقُولُوا آمِينَ. فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ",
 "ref": "صحيح البخاري 782 (من حديث أبي هريرة). في التأمين.",
 "exact": true
 }
 ],
