 "maliki": "الصبح: من أطول طوال المفصل. الظهر: من أقصر طوال المفصل. العصر: قصار المفصل. المغرب: قصاره. العشاء: أوساطه.",
 "shafii": "الصبح: طوال المفصل. الظهر: دون الصبح قليلاً. العصر: أوساطه. المغرب: قصاره. العشاء: أوساطه.",
 "hanbali": "الصبح: طوال المفصل. الظهر: أوساطه. العصر: أوساطه. المغرب: قصاره. العشاء: أوساطه."
