 "title": "سنن الصلاة: الركوع والرفع منه والهوي للسجود",
 "definition": "هذا الدرس في سنن الركوع: هيئته، والتسميع والتحميد (سنة عند الحنفية والمالكية والشافعية، واجب عند الحنابلة)، والذكر بعد الرفع، ورفع اليدين عند الركوع والرفع منه، وكيفية الهوي للسجود والنهوض منه. وذكر الركوع والسجود نفسهما (التسبيح) ليس في هذه الصفحات.",
 "hukm": "الخلاف هنا في الصفة والتصنيف: رفع اليدين عند الركوع سنة عند الشافعية والحنابلة وغير مشروع عند الحنفية والمالكية بحسب الموسوعة. وتقديم الركبتين على اليدين في الهوي هو سنة عند الحنفية والشافعية والحنابلة، والمالكية يندبون تقديم اليدين.",
 "pt": 1,
