 {
 "id": "e2",
 "type": "hadith",
 "text": "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَرْفَعُ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ إِذَا افْتَتَحَ الصَّلاَةَ، وَإِذَا كَبَّرَ لِلرُّكُوعِ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَهُمَا كَذَلِكَ أَيْضًا وَقَالَ \" سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ \". وَكَانَ لاَ يَفْعَلُ ذَلِكَ فِي السُّجُودِ.",
 "ref": "صحيح البخاري 735 (من حديث ابن عمر). في رفع اليدين عند افتتاح الصلاة وعند الركوع وعند الرفع منه، وفيه أنه لا يفعله في السجود. وهو الدليل الذي يستدل به من يقول بالرفع.",
 "exact": true
 }
