 "issue": "هيئة الركوع (ما نسب إلى مذهب)",
 "v": {
 "hanafi": "زادوا إلصاق الكعبين. وخصوا الهيئة العامة بالرجل: المرأة تنحني يسيراً ولا تفرج ولكن تضم، وتضع يديها على ركبتيها وضعاً، وتحني ركبتيها، ولا تجافي عضديها، لأن ذلك أستر لها.",
 "maliki": "لا زيادة منسوبة لهذا المذهب في الصفحات المقروءة. الهيئة العامة في بطاقة الهيئة العامة أعلاه.",
 "shafii": "لا زيادة منسوبة لهذا المذهب في الصفحات المقروءة. الهيئة العامة في بطاقة الهيئة العامة أعلاه.",
 "hanbali": "تقول الموسوعة في هذا الموضع عبارة قصيرة: وهو واجب عند الحنابلة، ولا تحدد ما المقصود بها. لذلك لا يبنى عليها حكم هنا. واجبات الحنابلة في الركوع المقروءة في موضعها هي تكبيرة الانتقال والتسبيح مرة واحدة (درس الواجبات)."
 },
 "note": "الهيئة العامة غير منسوبة لمذهب في الموسوعة، فهي في بطاقة مستقلة وليست في خلية مذهب."
