 "maliki": "مكروهة كراهة تنزيه لمن ليس به عذر.",
 "shafii": "سنة بعد السجدة الثانية في كل ركعة يقوم منها.",
 "hanbali": "مكروهة كراهة تنزيه لمن ليس به عذر."
