 "definition": "درس في مكان سجود السهو (قبل السلام أو بعده) وكيفية أدائه (التشهد والسلام) عند المذاهب الأربعة. يكمل درس سجود السهو في أسبابه.",
 "hukm": "أماكن سجود السهو تختلف: الحنفية بعد السلام، والشافعية قبله، والمالكية قبله للنقص وبعده للزيادة، والحنابلة يجوز الأمران والأفضل قبله إلا حالتين. والتفصيل في جدول الخلاف.",
