 "t": "المصدر",
 "d": "المصدر هنا كتاب الفقه الإسلامي وأدلته للزحيلي، وهو كتاب فقه مقارن حديث. وهو غير الموسوعة الفقهية الكويتية المستعملة في بقية الدروس، لأن الموسوعة لا تصف كيفية السجدتين. ولم تراجع الإحالات الواردة فيه إلى كتب المذاهب. وأضيف تسلسل الحنفية الكامل من فتوى الإسلام سؤال وجواب رقم 633915 (https://islamqa.info/ar/answers/633915) لأن مصدر الزحيلي لا يذكر السلام الأخير. والنص منقول من نسخة على الإنترنت ولم يقابل بالطبعة المطبوعة، فتبقى هذه الصفة بلا ادعاء توثيق نهائي.",
