 "t": "واركعوا مع الراكعين",
 "d": "قال تعالى: وأقيموا الصلاة وآتوا الزكاة واركعوا مع الراكعين. قال السعدي: أي صلوا مع المصلين، وفهم من الآية الأمر بالجماعة ووجوبها. وهذا فهمه هو لها، وقد اختلف الفقهاء في حكم الجماعة، ويبين تبويب الخلاف أقوال المذاهب. وذكر أن الأمر بالركوع يدل على أن الركوع ركن لأنه عبر عن الصلاة بجزئها.",
