 "maliki": "يعيد من صلى وحده مع الجماعة ما خلا المغرب وعشاءً بعد وتر، ولم يرد في المقطع المقروء استثناء للعصر والفجر من هذا العموم (حاشية الدسوقي ).",
 "shafii": "يسن للمصلي وحده، وكذا جماعة في الأصح، إعادة المكتوبة المؤداة مرة فقط مع جماعة يدركها في الوقت، ولو كان الوقت وقت كراهة، وتكون الثانية نافلة (مغني المحتاج ).",
