 "t": "فانتشروا في الأرض واذكروا الله",
 "d": "قال تعالى: فإذا قضيت الصلاة فانتشروا في الأرض وابتغوا من فضل الله واذكروا الله كثيراً لعلكم تفلحون. قال السعدي: لما كان الاشتغال بالتجارة مظنة الغفلة عن ذكر الله أمر الله بالإكثار من ذكره، وهو أكبر أسباب الفلاح.",
