 "maliki": "يندب في الثانية أيضاً الغاشية أو الأعلى. قال الدسوقي: مخير في الثانية بين الثلاث (الغاشية أو الأعلى أو المنافقون) وكلها يحصل به الندب لكن الغاشية أقوى في الندب. وفي كلام بعضهم أنها ذات قولين: الاقتصار على الغاشية مذهب المدونة، والتخيير بين الثلاث قول الكافي.",
 "shafii": "يستحب الأعلى في الأولى والغاشية في الثانية. وصرح الماوردي بأن الجمعة والمنافقين أولى. قال النووي: هما سنتان. وقال المحلي: لو ترك الجمعة في الأولى قرأها مع المنافقين في الثانية، ولو قرأ المنافقين في الأولى قرأ الجمعة في الثانية.",
