 "d": "قال تعالى: وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا من الصلاة. قال السعدي: الآية أصل في رخصة القصر وصلاة الخوف، وقال إن الرخصة سهولة من الله لعباده إذا سافروا أن يقصروا ويفطروا. وذكر أن نفي الحرج لا ينافي كون القصر هو الأفضل ولا ينافي الوجوب، وأن ظاهر الآية الترخص في أي سفر كما هو مذهب أبي حنيفة، وخالفه الجمهور في سفر المعصية. وتفصيل المذاهب في تبويب الخلاف.",
