 "issue": "حكم الجماعة في الصلوات المفروضة",
 "v": {
 "hanafi": "في الأصح: سنة مؤكدة للرجال، وهي شبيهة بالواجب في القوة. وصرح بعضهم بأنها واجبة بحسب اصطلاحهم. وقال بعض فقهائهم كالكرخي والطحاوي: فرض كفاية. وهناك قول لبعضهم بأنها واجبة وجوب عين. ومن أدلتهم كما تنقل الموسوعة حديث تفضيل الجماعة على الفذ بسبع وعشرين درجة، وأن ابن مسعود قال إنها من سنن الهدى، وهي غير مخرجة هنا.",
 "maliki": "أكثرهم: سنة مؤكدة للرجال. ونقل المازري عن بعضهم أنها فرض كفاية. وفصل بعضهم فقالوا: فرض كفاية من حيث الجملة، أي في البلد، فيقاتل أهلها عليها إذا تركوها، وسنة في كل مسجد، وفضيلة للرجل في خاصة نفسه.",
 "shafii": "في الأصح: فرض كفاية، واستدلوا بحديث: ما من ثلاثة في قرية ولا بدو لا تقام فيهم الصلاة إلا قد استحوذ عليهم الشيطان، وهو حديث تنقله الموسوعة ولم نخرجه. وفي المذهب قول بأنها سنة مؤكدة، وقول بأنها واجبة وجوب عين. وفي صلاة الخوف الجماعة أفضل من الانفراد.",
 "hanbali": "واجبة وجوب عين وليست شرطاً لصحة الصلاة. وخالف ابن عقيل فجعلها شرطاً في صحتها. واستدلوا بالآية (أمر بالجماعة حال الخوف) وبحديث أبي هريرة في همه صلى الله عليه وسلم بتحريق بيوت المتخلفين، وبحديث الأعمى الذي لم يرخص له (غير مخرجين هنا). وقالوا إن تارك الجماعة يقاتل وإن أقامها غيره لأن وجوبها على الأعيان."
 },
