 "d": "القريتان المتدانيتان اللتان اتصل بناء إحداهما بالأخرى أو يرتفق أهل إحداهما بالأخرى كالقرية الواحدة، وإلا فلكل قرية حكم نفسها: يقصر إذا جاوز بيوتها والأبنية التي في طرفها. وساكن الخيام يقصر إذا فارق خيام قومه ومرافقها كملعب الصبيان. ويقصر سكان القصور والبساتين وأهل العزب إذا فارقوا ما نسبوا إليه بما يعد مفارقة عرفاً. وتفاصيل أخرى منسوبة لمذهب في الجدول.",
