 "khilaf": [
 {
 "id": "q1",
 "issue": "اقتداء المسافر بالمقيم",
 "v": {
 "hanafi": "يصح في الوقت، وينقلب فرض المسافر أربعاً عند عامة الفقهاء من الحنفية لأنه صار تبعاً للإمام. ولا يصح خارج الوقت لأن الصلاة خارج الوقت قضاء، والأداء لم يتغير فلا يتغير القضاء، فتبقى ركعتين وتصير القعدة الأولى فرضاً في حقه ونفلاً في حق الإمام فيكون اقتداء المفترض بالمتنفل في القعدة، فلا يجوز.",
 "maliki": "يجوز مع الكراهة، ويلزمه الإتمام ولو نوى القصر لمتابعة الإمام. وهذا إذا أدرك معه ركعة. واختلف في الإعادة لمخالفة سنة القصر.",
 "shafii": "يجوز، ويلزمه الإتمام.",
 "hanbali": "يجوز، ويلزمه الإتمام."
 },
 "note": "وتنقل الموسوعة قولاً عن طاوس والشعبي وتميم بن حذلم: إن أدرك المسافر مع الإمام المقيم ركعتين أجزأتا عنه. وعن الحسن والزهري والنخعي وقتادة: إن أدرك ركعة فأكثر أتم وإن أدرك أقل من ركعة قصر. وهؤلاء ليسوا من الأئمة الأربعة."
 },
 {
 "id": "q2",
 "issue": "اقتداء المقيم بالمسافر",
 "v": {
 "hanafi": "يصح اقتداء المقيم بالمسافر في الوقت وبعده، ويتم المقيم صلاته بعد سلام المسافر. (كتاب تبيين الحقائق شرح كنز الدقائق)",
 "maliki": "يجوز مع الكراهة، ويسلم المسافر ويتم المقيم.",
 "shafii": "يجوز اقتداء المقيم بالمسافر، فإذا سلم الإمام قام المقيم فأتم لنفسه الصلاة. (كتاب الأساس في السنة وفقهها العبادات في الإسلام)",
 "hanbali": "يجوز اقتداء المقيم بالمسافر. فإذا سلم الإمام المسافر من ركعتين أتم المقيم صلاته بعد سلام إمامه إجماعاً، ويسن للإمام المسافر أن يقول للمقيمين: أتموا فإنا سفر (كشاف القناع)."
 },
 "note": "سلام الإمام المسافر وإتمام المقيم منصوص للحنفية والمالكية والحنابلة في الصفحات المقروءة. نص الحنابلة مقروء في كشاف القناع: https://shamela.ws/book/21642/505"
 },
 {
 "id": "q3",
 "issue": "قضاء فائتة السفر في الحضر وعكسه",
 "v": {
 "hanafi": "من فاتته صلاة في السفر قضاها في الحضر ركعتين، ومن فاتته في الحضر قضاها في السفر أربعاً، لأن القضاء بحسب الأداء. والمعتبر آخر الوقت. وخالف زفر: إذا سافر وقد بقي من الوقت قدر ما يمكنه أن يصلي فيه صلاة السفر يقضي صلاة السفر، وإن كان الباقي دونه صلى صلاة المقيم.",
 "maliki": "من فاتته في السفر قضاها في الحضر ركعتين، ومن فاتته في الحضر قضاها في السفر أربعاً.",
 "shafii": "هذا في القديم. وفي الجديد، وهو الأصح: من فاتته في السفر وقضاها في الحضر لا يجوز له القصر لأنه تخفيف تعلق بعذر فزال. وإن فاتته في السفر فقضاها في السفر فقولان: لا يقصر، أو يقصر وهو الأصح. وإن فاتته في الحضر فقضاها في السفر لم يجز القصر، وقال المزني: له أن يقصر.",
 "hanbali": "من نسي صلاة حضر فذكرها في السفر، أو نسي صلاة سفر فذكرها في الحضر صلى في الحالتين صلاة حضر. نص عليه أحمد في رواية أبي داود والأثرم، لأن القصر رخصة من رخص السفر فيبطل بزواله."
 },
 "note": "المزني من أصحاب الشافعي، وزفر من الحنفية، ولا يمثلان المذهب بإطلاق."
 }
 ],
