 "issue": "أقل مسافة السفر",
 "v": {
 "hanafi": "مسيرة ثلاثة أيام ولياليها. وتذكر الموسوعة من أدلتهم حديث علي في مدة المسح للمسافر وحديث سفر المرأة بلا محرم، وهما غير مخرجين هنا.",
 "maliki": "مسيرة يومين معتدلين بلا ليلة، أو مسيرة ليلتين معتدلتين بلا يوم، أو مسيرة يوم وليلة. قدروا السفر بثمانية وأربعين ميلاً وهي أربعة برد. وتذكر الموسوعة من أدلة هذا القول حديثاً وأثراً عن ابن عمر وابن عباس، غير مخرجين هنا.",
 "shafii": "مسيرة يومين معتدلين بلا ليلة، أو مسيرة ليلتين معتدلتين بلا يوم، أو مسيرة يوم وليلة. قدروا السفر بثمانية وأربعين ميلاً وهي أربعة برد. وتذكر الموسوعة من أدلة هذا القول حديثاً وأثراً عن ابن عمر وابن عباس، غير مخرجين هنا.",
 "hanbali": "مسيرة يومين معتدلين بلا ليلة، أو مسيرة ليلتين معتدلتين بلا يوم، أو مسيرة يوم وليلة. قدروا السفر بثمانية وأربعين ميلاً وهي أربعة برد. وعن أحمد في جواب سؤال: في أربعة برد، ستة عشر فرسخاً، مسيرة يومين."
 },
 "note": "المسافة بالأيام هنا حسب سير الإبل والأقدام. وتحويل الأميال والفراسخ إلى كيلومترات لم تذكره الموسوعة في هذه الصفحات، فلا نكتبه هنا. والوسائل الحديثة (القطار والطائرة) لم تقرأ."
