 "maliki": "أكثرها ثمان، لحديث أم هانئ (البخاري ومسلم). وصرحوا بكراهة ما زاد على ثمان إن صلاها بنية الضحى لا بنية نفل مطلق. وأوسطها ست.",
 "shafii": "في الوجه المرجوح اثنتا عشرة. واختلفت عبارات النووي: في المنهاج أكثرها اثنتا عشرة، وفي شرح المهذب حكى عن الأكثرين ثمان، وفي الروضة: أفضلها ثمان وأكثرها اثنتا عشرة ويسلم من كل ركعتين.",
 "hanbali": "على المذهب أكثرها ثمان، وفي رواية عن أحمد اثنتا عشرة."
