 "maliki": "الثلث الأخير لمن عادته الانتباه آخر الليل، ومن لا ينتبه غالباً فأول الليل احتياطاً.",
 "shafii": "السدس الرابع والخامس مطلقاً بحسب الموسوعة. وإن جعله أثلاثاً فالثلث الأوسط أفضل (في مدخل التهجد).",
