 "t": "ما نقلته الموسوعة في تاريخ مشروعيتها",
 "d": "نقلت حديث عائشة أن النبي ﷺ صلى في المسجد فصلى بصلاته ناس، ثم كثروا في الليلة التالية، فلم يخرج في الرابعة وقال: خشيت أن تفرض عليكم (البخاري ومسلم كما في تخريج الموسوعة). ونقلت حديث أبي ذر في ليالي القيام في الأيام السبع الأواخر، وحديث النعمان بن بشير في ليالي ثلاث وعشرين وخمس وعشرين وسبع وعشرين (حديث أبي ذر عند أبي داود والترمذي وقال: حسن صحيح، وحديث النعمان عند النسائي والحاكم وحسنه الذهبي، كما في تخريج الموسوعة). ثم جمع عمر الناس على إمام واحد، وكان ذلك في السنة الرابعة عشرة من الهجرة، لنحو سنتين خلتا من خلافته بحسب الموسوعة، وفي أثره: نعمت البدعة هذه (البخاري كما في تخريج الموسوعة). وروى أسد بن عمرو عن أبي يوسف أنه سأل أبا حنيفة عن التراويح وما فعله عمر فقال: التراويح سنة مؤكدة (والجملة بعدها مقطوعة في فلم تؤخذ).",
