 "maliki": "العمد مبطل اتفاقاً. وأما من أكل أو شرب سهواً فلا تبطل صلاته وينجبر بسجود السهو.",
 "shafii": "تبطل بالأكل ولو قليلاً ولو مكرهاً. ويستثنون الناسي أنه في الصلاة، والجاهل بالتحريم لقرب عهده بالإسلام أو نشأ بعيداً عن العلماء، فلا تبطل إلا إذا كثر عرفاً. وتبطل بالمضغ الكثير وإن لم يصل إلى جوفه شيء.",
 "hanbali": "في صلاة الفرض: تبطل بالأكل والشرب عمداً، قل أو كثر. وفي النفل: لا تبطل إلا إذا كثر عرفاً (رواية)، وعنه أن النفل كالفرض وبه قال أكثرهم. وأما السهو أو الجهل فلا يبطل إن كان يسيراً."
