 "t": "شروط الوجوب كما تلخصها الموسوعة (خمسة)",
 "d": "الإقامة، والذكورة، والصحة، والحرية، والسلامة، بعد العقل والبلوغ. فلا تجب على المسافر ولا المرأة ولا المريض ولا العبد (ويلحق بالمريض ممرضه إن لم يوجد من يقوم مقامه). وتجب على المكاتب والمبعض والأجير، ولا يجوز للمستأجر منعه، فإن ترك العمل لها وكان المسجد بعيداً سقط من أجرته ما يقابل الزمن. وهذه الحرية محل اتفاق في المذاهب بحسب الموسوعة. ولا تجب عند خوف من عدو أو سبع أو لص أو سلطان، ولا عند مطر شديد أو وحل أو ثلج يتعسر معه الخروج.",
