     "d": "الحنفية: لو سلم الإمام بعد الثالثة ناسياً كبر الرابعة ويسلم. الحنابلة: إن ترك غير مسبوق تكبيرة عمداً بطلت، وإن سهواً كبرها ما لم يطل الفصل. الشافعية: تبطل صلاة الجميع إن كان النقص عمداً من الإمام، وإن سهواً تداركه ولا سجود للسهو. المالكية: إن كان النقص من الإمام عمداً بطلت صلاة الجميع، وإن سهواً سبح له المأمومون.",
     "ref": "الموسوعة الفقهية الكويتية، مدخل جنائز: https://muslim-library.com/keoj/volume/16/10083/"
