     "maliki": "قولان: فرض على الكفاية (ابن عبد الحكم وسحنون وعليه الأكثر وشهره الفاكهاني)، وقال أصبغ: سنة على الكفاية.",
     "shafii": "فرض على الكفاية (قول جمهور الفقهاء كما في الموسوعة).",
     "hanbali": "فرض على الكفاية (قول جمهور الفقهاء كما في الموسوعة)."
