  "definition": "الخوف: توقع مكروه عن أمارة مظنونة أو متحققة، ويطلق على القتال. وليس المراد من إضافة الصلاة إلى الخوف أنه يقتضي صلاة مستقلة كصلاة العيد، ولا أنه يؤثر في قدر الصلاة ووقتها كالسفر. فشروط الصلاة وأركانها وسننها وعدد ركعاتها في الخوف كما في الأمن، وإنما يؤثر الخوف في كيفية إقامة الفرائض إذا صليت جماعة. الدرس من مدخل (صلاة الخوف) في الموسوعة الفقهية الكويتية، المجلد السابع والعشرين.",
