     "maliki": "قال ابن القصار: إذا كان الخوف في الحضر صلى بكل طائفة ركعتين، ولو ثبت أنه ﷺ كان في سفر وصلى بكل طائفة ركعتين لكان ذلك خاصًا به للفضيلة. (أحكام القرآن لابن الفرس، نقلًا عن ابن القصار)",
     "shafii": "تندب إذا كان العدو في غير جهة القبلة وكان في المسلمين كثرة والعدو قليل وخيف هجومهم: يصلي بفرقة الصلاة كلها ثم تذهب إلى وجه العدو وتأتي الأخرى فيصلي بها مرة ثانية، له نافلة ولهم فريضة.",
