     "maliki": "يصلى وحداناً ركعتين ركعتين، ولا يصلونها جماعة، لأن الجماعة لخسوف القمر لم تنقل عن النبي ﷺ. وفي «الجامع لمسائل المدونة» (ابن يونس، باب جامع ما جاء في صلاة الخسوف، ج3 ص931، ترقيم الشاملة) عن مالك: ولم أسمع أنه يجمع لخسوف القمر، ولكن يصلون أفذاذاً ركعتين ركعتين كسائر النوافل ويدعون ولا يجمعون.",
