     "hanbali": "إذا خسف القمر أو الشمس فزع الناس إلى الصلاة، إن أحبوا جماعة وإن أحبوا فرادى؛ لأنها نافلة فجازت في الانفراد، وفعلها في الجماعة أفضل. (المغني)"
