     "maliki": "يستقبل الإمام الناس في الخطبة مستدبراً القبلة، فإذا قضى خطبته توجه إلى القبلة يدعو.",
     "shafii": "يستقبل الإمام الناس في الخطبة مستدبراً القبلة، فإذا قضى خطبته توجه إلى القبلة يدعو.",
