  "hukm": "صلاة العيدين واجبة عند الحنفية على القول المفتى به، وسنة مؤكدة عند المالكية والشافعية، وفرض كفاية عند الحنابلة. ووقتها من ارتفاع الشمس قدر رمح إلى الزوال عند الجمهور، ومن طلوع الشمس عند الشافعية. وتؤدى ركعتين بتكبيرات زائدة ثم خطبتين، بلا أذان ولا إقامة. وفي كل ما سبق تفاصيل مختلفة بين المذاهب في خلايا مستقلة.",
