  "definition": "صلاة العيدين هي صلاة عيد الفطر وعيد الأضحى، تؤدى ركعتين في جماعة بكيفية مخصوصة. وهذا الدرس من مدخل (صلاة العيدين) في الموسوعة الفقهية الكويتية، المجلد السابع والعشرين، من حكمة المشروعية إلى الشعائر والآداب. وللتكبير في أيام التشريق مدخل مستقل في الموسوعة أحالت عليه (تكبير، المجلد 13)، وصلاة الاستسقاء والكسوف والخوف دروس مستقلة.",
